class A:
 @property
 def __dict__(self): return {"virtual":7}
print(*object.__dir__(A()))

class A:
 @property
 def __dict__(self):
  print("dictionary")
  return ["ignored"]
v=A()
print("ignored" in dir(v),"__class__" in dir(v))

class A:
 @property
 def __dict__(self):
  print("dictionary")
  raise AttributeError("missing")
print("__class__" in dir(A()))

class A:
 @property
 def __dict__(self):
  print("dictionary")
  raise ValueError("original")
dir(A())

class A:
 def __getattribute__(self,name):
  print(name)
  return object.__getattribute__(self,name)
v=A()
v.z=7
print("z" in dir(v))

class A:
 @property
 def __dict__(self): raise AttributeError("missing")
 def __getattr__(self,name):
  print(name)
  return {"virtual":7}
print("virtual" in dir(A()))

class B: advertised=7
class A:
 @property
 def __class__(self):
  print("class")
  return B
v=A()
v.own=8
print("own" in dir(v),"advertised" in dir(v))

class A:
 @property
 def __class__(self):
  print("class")
  raise AttributeError("missing")
v=A()
v.own=8
print(*dir(v))

class A:
 @property
 def __class__(self):
  print("class")
  raise ValueError("original")
dir(A())

saved={"original":7}
class B: base=1
class A:
 @property
 def __dict__(self): return saved
 @property
 def __class__(self):
  saved["later"]=9
  return B
v=A()
result=dir(v)
print("original" in result,"later" in result,"later" in saved)

class A:
 def __getattribute__(self,name):
  if name=="__dir__": raise RuntimeError("read")
  return object.__getattribute__(self,name)
v=A()
print("__class__" in object.__getattribute__(v,"__dir__")())

class Key:
 def __hash__(self): return hash("__doc__")
 def __eq__(self,other):
  print("equal",other)
  return other=="__doc__"
key=Key()
class A: pass
v=A()
v.__dict__={key:7}
result=object.__dir__(v)
print(result[0] is key,len(result))

class Truth:
 def __bool__(self):
  print("truth")
  return True
class Key:
 def __hash__(self): return hash("__doc__")
 def __eq__(self,other):
  print("equal",other)
  return Truth()
key=Key()
class A: pass
v=A()
v.__dict__={key:7}
print(object.__dir__(v)[0] is key)

class Key:
 def __hash__(self): return hash("__doc__")
 def __eq__(self,other):
  print("collision")
  raise ValueError("original")
key=Key()
class A: pass
v=A()
v.__dict__={key:7}
object.__dir__(v)

class Meta(type):
 @property
 def __dict__(cls): return {"virtual":7}
class A(metaclass=Meta): pass
print("virtual" in dir(A()))

class A:
 @property
 def __class__(self): return None
print(*dir(A()))

class Base: old=7
class A(Base): pass
class Key:
 def __hash__(self): return hash("__module__")
 def __eq__(self,other):
  Base.new=9
  return False
key=Key()
v=A()
v.__dict__={key:7}
result=object.__dir__(v)
print(result[0] is key,"new" in result)

class Key:
 def __hash__(self): return hash("__module__")
 def __eq__(self,other):
  if hasattr(A,"later"): del A.later
  return False
class A: later=7
key=Key()
v=A()
v.__dict__={key:8}
object.__dir__(v)
